states = {'A': 0, 'B': 1, 'C': 2}
delta = {('A','0'):'B', ('A','1'):'A', ('B','0'):'B', ('B','1'):'C', ('C','0'):'C', ('C','1'):'C'}
final = {'C'}
start = 'A'
def step(q, a):
    return delta[(q, a)]
def dhat(q, w):
    for a in w:
        q = step(q, a)
    return q
w1 = '1001'
w2 = '110'
q1 = dhat(start, w1)
q2 = dhat(start, w2)
print(states[q1])
print(states[q2])
print(1 if q1 in final else 0)
print(1 if q2 in final else 0)
